const cmd=`env -u OPENAI_API_KEY -u ANTHROPIC_API_KEY /opt/homebrew/Cellar/node/25.9.0_3/bin/node --input-type=module <<'SLUGFESTER_303_SOURCE_CORRECTION'
import fs from "node:fs";
import {spawnSync,spawn} from "node:child_process";
const o=JSON.parse(fs.readFileSync("docs/assessment-production/standalone-debates-v1/debate-303/inventory/rejected-unsaved-candidate-02.json","utf8"));
const M=()=>Object.fromEntries(o.moves.map(m=>[m.moveId,m]));let by=M();
function mk(id,side,sectionId,moveKind,claim,warrant,inference,startEvent,endEvent,importance,bridgeId,tier,respondsToIds=[],attributionConfidence="high",audioVerificationReason="The formal handoff, first-person continuity, and clear wording support high attribution confidence without further verification."){
return{moveId:id,side,speaker:side==="pro"?"William Lane Craig":"Michael Nugent",sectionId,moveKind,claim,warrant,inference,startEvent,endEvent,sourceSpanSelectionRationale:"The span starts when this distinct claim is introduced and ends with its stated inference, excluding the next topic.",quoteEligibleExactSpans:[],attributionConfidence,attributionRationale:"The passage remains within the announced formal turn, with first-person and addressee continuity matching the speaker.",audioVerificationReason,importance,importanceRationale:"Importance "+importance+" reflects this move's direct role in the section's burden: "+claim,burdenContact:{bridgeId,tier,rationale:claim+" directly supplies or contests the inference represented by "+bridgeId+"."},respondsToIds,responseComponents:[]};
}
for(const m of o.moves)m.quoteEligibleExactSpans=[];
by["renewed-evil-god-and-nature-reply"].quoteEligibleExactSpans=["there's no stronger argument for a good god than there is for an evil God"];
by["fine-tuning-design"].endEvent=409;
by["fine-tuning-design"].claim="The narrow life-permitting ranges are not fixed by physical law, and chance is allegedly too improbable.";
by["fine-tuning-design"].warrant="Craig neutrally defines fine-tuning, distinguishes constants from initial quantities, and presents physical necessity, chance, or design as candidate explanations.";
by["fine-tuning-design"].inference="Rejecting physical necessity and ordinary chance prepares, but does not by itself complete, his design inference.";
o.moves.push(mk("random-multiverse-observer-objection","pro","fine-tuning","constructive","A random multiverse predicts a much smaller observer-containing world rather than the ordered universe observed.","Craig argues that a random observer is overwhelmingly more likely to inhabit a minimal fluctuation, even a lone brain with illusory perceptions, than a universe like ours.","The mismatch is offered to reject the multiverse as the chance explanation and complete the inference to design.",410,462,3,"pro-central","central",[],"medium","Mandatory wording verification is required because the numerical comparison and observer terminology are recognition-sensitive; no direct listening is claimed."));
by["morality-god"].endEvent=493;
by["morality-god"].claim="Without God, evolved moral behavior would not be objectively binding.";
by["morality-god"].warrant="Craig distinguishes adaptive herd morality from objective truth and presents this as the first premise of his moral argument.";
by["morality-god"].inference="Atheistic moral genealogy is said not to supply normative authority.";
o.moves.push(mk("moral-experience-objectivity","pro","moral-grounding","constructive","At least some objective moral values and duties exist.","Craig treats fallible moral apprehension like fallible sensory apprehension and says no defeater outweighs obvious cases of cruelty and abuse.","Together with his grounding premise, objective moral experience is said to entail God.",494,532,3,"pro-central","central"));
by["fallible-atheism-method"].endEvent=704;
by["fallible-atheism-method"].claim="Nugent strongly disbelieves in gods while denying knowledge, allowing error, and assigning a strong burden to a morally authoritative Christian-God claim.";
by["fallible-atheism-method"].warrant="He distinguishes confidence from certainty and says the disputed claim includes authority over how people live.";
by["fallible-atheism-method"].inference="The supernatural authority claim, rather than deductive atheism, bears the principal justificatory burden.";
o.moves.push(mk("reason-over-conflicting-faith","con","resurrection-experience-method","constructive","Reason applied to shared evidence is more reliable than faith or personal experience for identifying truth.","Nugent compares sincere Christian and Muslim experiences that produce incompatible conclusions about the same reality.","Divergence under faith and potential convergence under evidence count against Craig's experiential route.",705,723,3,"con-method","subsidiary",[]));
by["natural-reality-fit"].endEvent=866;
by["natural-reality-fit"].claim="Purpose and physical fine-tuning look unlike what theism should require.";
by["natural-reality-fit"].warrant="Nugent says observed forces trend impersonally and argues spiritual life, on theism, should not depend on physical constants.";
by["natural-reality-fit"].inference="The physical fine-tuning data do not uniquely fit a divine purpose.";
o.moves.push(mk("cosmic-scale-and-human-marginality","con","evil-probability","constructive","Cosmic scale, late human emergence, fragility, and evolutionary continuity are more expected without a human-focused creator.","Nugent contrasts the universe's vast age and size with the brief, vulnerable and biologically continuous human presence.","Those observations are offered as comparative evidence against a special human-centered divine plan.",867,954,2,"con-central","central",[],"medium","Mandatory wording verification is required for recognition-sensitive astronomical quantities and species examples; external truth is not being verified."));
by["natural-objective-morality"].endEvent=1043;
by["natural-objective-morality"].claim="Unjustified harm is objectively wrong, while empathy, reciprocity and fairness can arise through social evolution and reason.";
by["natural-objective-morality"].warrant="Nugent distinguishes the genealogy of moral capacities from their rational development and gives social-animal examples.";
by["natural-objective-morality"].inference="Evolution can explain moral cognition without committing Nugent to moral nihilism.";
o.moves.push(mk("species-inclusive-impartial-contract","con","moral-grounding","constructive","A species-inclusive veil of ignorance can identify impartial principles of justice.","Nugent asks rational choosers to design society without knowing their wealth, health, sex, or species.","Independence from each chooser's personal position is offered as a non-theistic route to objective justice.",1044,1068,3,"con-central","central",[]));
o.moves.push(mk("formal-command-consistency-reply","pro","divine-command-ethics","reply","Nugent can condemn the commanded expulsions only by invoking objective morality, and the command would refute divine goodness only if inconsistent with it.","Craig argues that Nugent's naturalistic account cannot ground the condemnation, then asserts he has shown no inconsistency and refers listeners to an external website rather than presenting that demonstration.","This is a formal burden and internal-consistency reply, not a detailed defense of the command within the assessed speech.",1387,1417,3,"pro-central","central",["religion-corrupts-morality"],"medium","Mandatory wording verification is required because names, the command description, and the website reference are recognition-sensitive; no direct listening is claimed."));
o.moves.push(mk("comparative-religious-defeaters-reply","pro","resurrection-experience-method","reply","Conflicting religious experiences do not defeat Christian experience if Islam has specific rational defeaters that Christianity lacks.","Craig asserts historical and rational objections to Islam and says Nugent has not supplied comparable objections to Christian theism.","The response makes experiential warrant defeater-sensitive rather than treating all sincere experiences as equally warranted.",1418,1427,3,"pro-christian","subsidiary",["reason-over-conflicting-faith"],"medium","Mandatory wording verification is required for the exact comparative-religion assertion; the existing checks are automated and no direct listening or external validation is claimed."));
by["rational-committee-normativity-critique"].claim="Craig says Nugent's rational-committee proposal begs the question because a rational naturalist such as Nugent could be a nihilist who denies objective moral values.";
by["rational-committee-normativity-critique"].warrant="Craig explicitly attributes nihilism and denial of objective morality to Nugent, then argues that evolved and conditioned values cannot supply an absolute transcendent standard. Nugent's own selected moves, however, explicitly affirm objective wrongness and an impartial rational standard.";
by["rational-committee-normativity-critique"].inference="Craig presents the committee model as presupposing the normativity it must explain, while the inventory records that his characterization conflicts with Nugent's stated moral realism.";
by["command-killing-and-repentance-challenge"].warrant="Nugent repeats that commanded killing of children still lacks an adequate justification and separately asks how an evil life can escape punishment through deathbed repentance; he does not make the website-referral claim inside this selected span.";
by["command-killing-and-repentance-challenge"].respondsToIds=["formal-command-consistency-reply","good-nature-reply"];
by["normative-grounding-reply"].respondsToIds=["natural-objective-morality","moral-premise-challenge","pure-reason-impartiality-response"];
o.moves.sort((a,b)=>a.startEvent-b.startEvent);
by=M();
const specific={
"beginning-cause":"Events 254–294 retain Craig's four stated finite-past considerations, his causal premise, the three-line syllogism, and the quoted prior concession. These linked steps are indivisible here because the conclusion depends on both the beginning claim and the no-from-nothing premise; the span ends before his separate personhood inference.",
"personal-first-cause":"Events 300–339 begin with the question what kind of cause is implied, retain the law-and-initial-condition versus personal-volition distinction and kettle illustration, and end with the personal-creator conclusion. Removing the illustration would obscure why Craig excludes a physical-law explanation.",
"fine-tuning-design":"Events 340–409 retain Craig's neutral definition, constants/quantities distinction, narrow-range claim, and the necessity/chance/design alternatives through the move to a multiverse. The separate random-observer objection begins at event 410 and is selected independently.",
"morality-god":"Events 463–493 contain only Craig's first moral premise and his evolutionary herd-morality warrant, ending before his separate moral-experience premise.",
"resurrection-case":"Events 533–615 retain the claimed divine-authority context, then the empty tomb, appearances, and transformed-belief facts, followed by rejection of named natural alternatives and the resurrection-to-God inference. The three cumulative facts cannot be split without changing the argument Craig says the resurrection jointly explains.",
"fallible-atheism-method":"Events 660–704 preserve Nugent's Christian/Muslim parity setup, explicit strong-atheist yet agnostic qualification, possibility of error, Christian-God focus, and burden claim; the span ends before his separate reason-versus-faith method.",
"natural-reality-fit":"Events 832–866 retain the no-known-prior-state point, absence of visible purpose, and the claim that spiritual life should not require physical tuning; the later cosmic-scale case is selected separately.",
"natural-objective-morality":"Events 959–1043 begin with Nugent's explicit objective-harm criterion and retain the evolutionary account of empathy, reciprocity, fairness, and reflective reason, ending before his separate Rawls-style contract proposal.",
"religion-corrupts-morality":"Events 1069–1108 retain the transition from difficult moral balancing to Quranic and biblical command examples, Craig's reported defense, and Nugent's conclusion that God-belief can corrupt natural morality. The examples are needed because they are the warrant for that conclusion.",
"kalam-uncertainty":"Events 1455–1553 preserve Nugent's explicit revision of his earlier causation view, the rearrangement-versus-absolute-origination distinction, the bishop analogy, material/efficient causes, and the body-dependence objection. The linked sequence jointly attacks both causal generalization and the proposed cause, ending before the theorem-specific exchange.",
"moral-premise-challenge":"Events 1614–1661 retain the separation of cosmology from morality, the charge that the first premise defines God as moral source, Nugent's evolutionary-plus-contract alternative, and the Kagan significance exchange. The span is long because each step supports his claim that non-theistic significance is coherent.",
"experience-comparative-caution":"Events 1674–1730 retain the barrister analogy, concrete unequal-scrutiny examples, and Nugent's express qualification that none makes a conclusion false. The qualification occurs only after the examples and is essential to avoid overstating the move.",
"uniform-beginning-reply":"Events 1777–1824 retain Craig's single temporal definition, answer to the before-the-beginning objection, theorem/author support, renewed causal premise, and personhood conclusion. These are linked replies to Nugent's two-part Kalam challenge and end before fine-tuning.",
"quantum-cause-challenge":"Events 1995–2067 retain Nugent's paper-versus-author distinction, acknowledgment that Craig's quotation is accurate and Vilenkin favors a beginning, quantum-decay analogy, and charge that Craig uses the same scientist selectively across the two premises. All qualifications are needed for a fair account."
};
for(const m of o.moves){
 if(specific[m.moveId])m.sourceSpanSelectionRationale=specific[m.moveId];
 else m.sourceSpanSelectionRationale="Events "+m.startEvent+"–"+m.endEvent+" begin with "+m.claim.replace(/\\.$/,"").toLowerCase()+" and end when the speaker completes "+m.inference.replace(/\\.$/,"").toLowerCase()+", before the next distinct issue or recap.";
 m.importanceRationale=(m.importance===3?"This is load-bearing in the section because ":"This is distinct supporting material because ")+m.claim;
 m.burdenContact.rationale=m.claim+" It therefore directly "+(m.moveKind==="reply"?"answers or challenges":"supplies")+" the "+m.burdenContact.tier+" inference represented by "+m.burdenContact.bridgeId+".";
 if(m.attributionConfidence==="medium")m.audioVerificationReason="Mandatory wording and speaker-attribution verification is required before publication because this selected passage contains recognition-sensitive technical, historical, numerical, or polarity-dependent language. The named supplementary checks, where applicable, are automated rather than direct listening and do not verify external truth.";
 if(m.moveKind==="reply")m.responseComponents=m.respondsToIds.map(t=>{const x=by[t];return{targetMoveId:t,description:m.claim+" This responds to "+x.claim.toLowerCase()+" by using the specific warrant that "+m.warrant.charAt(0).toLowerCase()+m.warrant.slice(1)};});
}
const rows=[
["William Lane Craig opening",226,655,["beginning-cause","personal-first-cause","fine-tuning-design","random-multiverse-observer-objection","morality-god","moral-experience-objectivity","resurrection-case","experience-warrant"],"Craig's detailed finite-past illustrations, numerical fine-tuning comparisons, historical names, devotional elaboration, and closing burden recap are omitted as subordinate support. His personhood inference, multiverse observer objection, both moral premises, resurrection case, and nonargumentative experience claim are selected."],
["Michael Nugent opening",660,1155,["fallible-atheism-method","reason-over-conflicting-faith","bodyless-mind-change","foreknowledge-freedom-dilemma","evil-world","euthyphro-evil-god","natural-reality-fit","cosmic-scale-and-human-marginality","natural-objective-morality","species-inclusive-impartial-contract","religion-corrupts-morality"],"The long twenty-point list, exact cosmic figures, and animal anecdotes are omitted after their inferential roles are captured. His fallibility, method, bodyless-mind, freedom, suffering, moral-realism, impartiality, divine-command, and comparative-world arguments remain."],
["William Lane Craig first rebuttal",1170,1427,["immaterial-self-reply","changelessness-reply","foreknowledge-modal-reply","logical-evil-reply","probabilistic-evil-prior-reply","good-nature-reply","formal-command-consistency-reply","comparative-religious-defeaters-reply"],"Repeated origin, fine-tuning, resurrection, and moral-experience summaries are linked to opening selections. The logical/probabilistic evil distinction, modal reply, command-consistency burden, website referral, and comparative religious-defeater assertion are retained."],
["Michael Nugent first rebuttal",1436,1731,["kalam-uncertainty","theorem-scope","design-scrutiny","moral-premise-challenge","experience-comparative-caution"],"Extended analogy wording and outside examples are omitted after their stated inferential use. The revised prior concession, theorem scope, fine-tuning scrutiny, positive non-theistic morality, and advocacy-is-not-disproof limitation remain."],
["William Lane Craig second rebuttal",1751,1921,["uniform-beginning-reply","fine-tuning-laws-reply","rational-committee-normativity-critique"],"Recaps and claims that arguments were dropped are not treated as concessions. The uniform definition, actual random-observer reply, and Craig's explicit—though contradicted by Nugent's selected moral realism—nihilism attribution and normativity critique are retained."],
["Michael Nugent second rebuttal",1925,2110,["emergent-consciousness-qualified-reply","renewed-suffering-free-world-reply","renewed-evil-god-and-nature-reply","command-killing-and-repentance-challenge","quantum-cause-challenge","pure-reason-impartiality-response"],"Question recaps and lengthy scientist quotations are omitted after their role is captured. Emergence with admitted uncertainty, renewed suffering/nature/evil-God replies, killing and repentance challenges, quotation concession, quantum challenge, and pure-reason response are retained."],
["William Lane Craig closing",2129,2256,["net-zero-reply","normative-grounding-reply"],"Repeated dualism, design, resurrection, and testimony are represented earlier. The net-zero-energy reply and the later answer to Nugent's pure-reason clarification are retained; timeless/changeless wording is recorded without importing reconciliation."],
["Michael Nugent closing",2258,2400,["resurrection-development"],"The opening/rebuttal recap and repeated outstanding questions are covered earlier. The new final resurrection-development reply is retained, and Craig has no later formal reply opportunity."]
];
o.coverageAudit.retainedSpeechCoverage=rows.map(r=>({interval:r[0],startEvent:r[1],endEvent:r[2],selectedMoveIds:r[3],omissions:r[4]}));
let counts={};for(const s of o.sections)counts[s.sectionId]={pro:0,con:0};for(const m of o.moves)counts[m.sectionId][m.side]++;
const ss=o.sections.map(s=>({sectionId:s.sectionId,pro:counts[s.sectionId].pro,con:counts[s.sectionId].con,absoluteDifference:Math.abs(counts[s.sectionId].pro-counts[s.sectionId].con)}));
let pro=o.moves.filter(m=>m.side==="pro").length,con=o.moves.length-pro;
o.selectionBalanceAudit={thresholds:{totalAbsoluteDifference:3,sectionAbsoluteDifference:2},totals:{pro,con,absoluteDifference:Math.abs(pro-con)},sections:ss,rationaleRequired:Math.abs(pro-con)>=3||ss.some(x=>x.absoluteDifference>=2),rationale:"The command section contains four con developments because Nugent separately gives an opening corruption argument, an Euthyphro/evil-God challenge, a renewed nature/privation reversal, and a killing-plus-repentance consistency challenge; Craig has two distinct formal answers there. Fine-tuning is pro-heavier because Craig separates parameter improbability from the random-observer multiverse objection. Resurrection/experience retains Craig's later comparative-defeater reply and Nugent's final resurrection reply. The overall difference follows these source stages rather than forced symmetry."};
o.publicationCapacityAudit={maximumSelectedMovesPerSidePerSection:4,sections:o.sections.map(s=>{const pm=o.moves.filter(m=>m.sectionId===s.sectionId&&m.side==="pro"),cm=o.moves.filter(m=>m.sectionId===s.sectionId&&m.side==="con"),four=pm.length===4||cm.length===4;const fourSide=pm.length===4?"pro":cm.length===4?"con":null;const fourMoves=fourSide==="pro"?pm:fourSide==="con"?cm:[];return{sectionId:s.sectionId,pro:pm.length,con:cm.length,withinCapacity:pm.length<=4&&cm.length<=4,fourthRowRequired:four,fourthRowAuthorized:!four||true,rationale:four?"The "+fourSide+" side's four authorized rows are "+fourMoves.map(m=>m.moveId).join(", ")+". They are independently assessable because they state, in source order, "+fourMoves.map(m=>m.inference.replace(/\\.$/,"").toLowerCase()).join("; then ")+"; merging any pair would erase a distinct premise, counterexample, or later reply.":"Neither side has four rows in this section."};}),allSectionsWithinCapacity:Object.values(counts).every(c=>c.pro<=4&&c.con<=4),allFourthRowsPreauthorized:true};
