const q=spawnSync("/opt/homebrew/Cellar/node/25.9.0_3/bin/node",["docs/assessment-production/standalone-debates-v1/debate-303/inventory/check-inventory.mjs","--debate","303"],{input:bytes,encoding:"utf8",env});process.stdout.write("CHECK_EXIT "+q.status+"\\n"+q.stdout+q.stderr);if(q.status!==0)process.exit(q.status||1);
